-- DANCE_CONTENT_PAGE_SEEDS: guarantee legal/information pages exist before the dance-specific updates.
INSERT OR IGNORE INTO content_pages(page_key,title,body_text,body_html,sort_order) VALUES
('about','About IronPulse Gym','IronPulse Gym is a fitness center offering online, gym and hybrid classes for beginners, enthusiasts and experienced athletes.

Members can choose membership plans, workshops and coaching options based on their level, preferred Fitness Specialty and schedule. Class plans, prices, availability and offers are managed from the website admin panel.

Our goal is to make fitness training easy to discover and simple to manage, whether you prefer learning from home or training at the gym. Class schedules, instructors and availability may change, so the latest information shared by the gym will apply.','<p>IronPulse Gym is a fitness center offering online, gym and hybrid classes for beginners, enthusiasts and experienced athletes.</p><p>Members can choose membership plans, workshops and coaching options based on their level, preferred Fitness Specialty and schedule. Class plans, prices, availability and offers are managed from the website admin panel.</p><p>Our goal is to make fitness training easy to discover and simple to manage, whether you prefer learning from home or training at the gym. Class schedules, instructors and availability may change, so the latest information shared by the gym will apply.</p>',1),
('contact','Contact IronPulse Gym','Need help choosing a class, booking a trial, checking a membership, confirming a payment or understanding an online or gym schedule? Send your details through the contact form and the gym team will respond.

You can also use the order tracking page with your registered WhatsApp number when you need membership or payment status information.','<p>Need help choosing a class, booking a trial, checking a membership, confirming a payment or understanding an online or gym schedule? Send your details through the contact form and the gym team will respond.</p><p>You can also use the order tracking page with your registered WhatsApp number when you need membership or payment status information.</p>',2),
('privacy','Privacy Policy','This Privacy Policy explains how IronPulse Gym collects, uses and protects information provided through this website, trial-class enquiries, contact forms, checkout, order tracking and connected communication services.

We may collect information such as name, phone number, email address, class interests, membership and order information, payment status and support messages. This information is used to manage enquiries, memberships, class communication, payments, support and website operations.

Payments are processed by enabled third-party payment gateways. We do not store full card numbers, CVV, UPI PINs or online-banking passwords. Payment references and status information may be stored for reconciliation and support.

The website may use analytics, advertising pixels, cookies and visitor logs when enabled by the administrator. These tools help measure website performance and marketing activity. We do not sell personal information. Limited information may be shared with payment, messaging, email, analytics or automation providers only where required to operate the service.

You may contact the gym to request correction of your contact information or assistance with communication preferences, subject to records that must be retained for payment, legal or operational purposes.','<p>This Privacy Policy explains how IronPulse Gym collects, uses and protects information provided through this website, trial-class enquiries, contact forms, checkout, order tracking and connected communication services.</p><p>We may collect information such as name, phone number, email address, class interests, membership and order information, payment status and support messages. This information is used to manage enquiries, memberships, class communication, payments, support and website operations.</p><p>Payments are processed by enabled third-party payment gateways. We do not store full card numbers, CVV, UPI PINs or online-banking passwords. Payment references and status information may be stored for reconciliation and support.</p><p>The website may use analytics, advertising pixels, cookies and visitor logs when enabled by the administrator. These tools help measure website performance and marketing activity. We do not sell personal information. Limited information may be shared with payment, messaging, email, analytics or automation providers only where required to operate the service.</p><p>You may contact the gym to request correction of your contact information or assistance with communication preferences, subject to records that must be retained for payment, legal or operational purposes.</p>',3),
('terms','Terms & Conditions','These Terms & Conditions apply to use of the DropBeat Dance Studio website, class memberships, workshops, online sessions, studio sessions, payments, order tracking and related services.

Membership provides access to the class plan and benefits described at the time of purchase. Class schedules, instructors, venues, online links and workshop availability may change when operationally necessary. The latest schedule or communication issued by the studio will apply.

Students are responsible for choosing a class suitable for their age, experience and physical ability, following instructor guidance and providing accurate contact details. Participation in physical activity involves normal exercise-related risk; students should use appropriate judgment and seek professional advice where needed.

Plans, pricing, offers, billing cycles, validity and access conditions may change for new purchases. Recurring payments and cancellations are also subject to the rules of the enabled payment gateway.

Misuse of class links, paid materials, member-only information, abusive behaviour, spam or violation of studio rules may lead to suspension or cancellation of access.','<p>These Terms &amp; Conditions apply to use of the DropBeat Dance Studio website, class memberships, workshops, online sessions, studio sessions, payments, order tracking and related services.</p><p>Membership provides access to the class plan and benefits described at the time of purchase. Class schedules, instructors, venues, online links and workshop availability may change when operationally necessary. The latest schedule or communication issued by the studio will apply.</p><p>Students are responsible for choosing a class suitable for their age, experience and physical ability, following instructor guidance and providing accurate contact details. Participation in physical activity involves normal exercise-related risk; students should use appropriate judgment and seek professional advice where needed.</p><p>Plans, pricing, offers, billing cycles, validity and access conditions may change for new purchases. Recurring payments and cancellations are also subject to the rules of the enabled payment gateway.</p><p>Misuse of class links, paid materials, member-only information, abusive behaviour, spam or violation of studio rules may lead to suspension or cancellation of access.</p>',4),
('refund','Refund & Cancellation Policy','This Refund & Cancellation Policy explains how membership cancellation, failed payments and refund requests are handled for DropBeat Dance Studio services.

Cancellation requests can be submitted using the contact details shown on the website. Please include the registered phone number, Order ID and reason so the studio can identify the membership correctly.

A cancellation does not automatically create a refund. Refund eligibility depends on the selected plan, whether access or classes have already started, the reason for the request and the applicable payment-gateway rules. Duplicate payments or verified technical payment errors may be reviewed for refund.

If a payment fails but money is debited, reversal timing is generally controlled by the bank, card issuer, UPI provider or payment gateway. Approved refunds are returned through the applicable payment method and may take additional processing time.','<p>This Refund &amp; Cancellation Policy explains how membership cancellation, failed payments and refund requests are handled for DropBeat Dance Studio services.</p><p>Cancellation requests can be submitted using the contact details shown on the website. Please include the registered phone number, Order ID and reason so the studio can identify the membership correctly.</p><p>A cancellation does not automatically create a refund. Refund eligibility depends on the selected plan, whether access or classes have already started, the reason for the request and the applicable payment-gateway rules. Duplicate payments or verified technical payment errors may be reviewed for refund.</p><p>If a payment fails but money is debited, reversal timing is generally controlled by the bank, card issuer, UPI provider or payment gateway. Approved refunds are returned through the applicable payment method and may take additional processing time.</p>',5),
('faq','Frequently Asked Questions','Find answers about online and studio dance classes, memberships, trial enquiries, payments, renewals, cancellations and order tracking. The administrator can edit this page and the FAQ items from the admin panel.','<p>Find answers about online and studio dance classes, memberships, trial enquiries, payments, renewals, cancellations and order tracking. The administrator can edit this page and the FAQ items from the admin panel.</p>',6),
('404','Page Not Found','The page you are looking for could not be found. Please check the link, return to the home page, browse dance memberships or contact DropBeat Dance Studio for help.','<p>The page you are looking for could not be found. Please check the link, return to the home page, browse dance memberships or contact DropBeat Dance Studio for help.</p>',7);

